import{_ as e,c as a,o as i,aj as o}from"./chunks/framework.lC5GZWV9.js";const u=JSON.parse('{"title":"Trakt","description":"","frontmatter":{},"headers":[],"relativePath":"importing/trakt.md","filePath":"importing/trakt.md","lastUpdated":1787419770000}'),r={name:"importing/trakt.md"};function s(l,t,n,c,h,d){return i(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="trakt" tabindex="-1">Trakt <a class="header-anchor" href="#trakt" aria-label="Permalink to “Trakt”">​</a></h1><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>It is necessary to set up TMDB for any Trakt import, including ZIP exports. Please follow the configuration <a href="./../configuration.html">guide</a> for instructions.</p></div><p>Ryot supports three Trakt import methods: a public user, a public list, or a ZIP export. The User and List methods use the Trakt API and, on a self-hosted instance, require a Trakt client ID in the environment variables as described in the <a href="./../guides/trakt.html">guide</a>. The Export ZIP method does not require a Trakt client ID.</p><h2 id="user" tabindex="-1">User <a class="header-anchor" href="#user" aria-label="Permalink to “User”">​</a></h2><p>All movies and shows can be imported from <a href="https://trakt.tv" target="_blank" rel="noreferrer">Trakt</a> along with their ratings, history, comments and lists.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>It is necessary to set your account&#39;s privacy to public during the duration of the import. Also, items that have been &quot;check(ed) in&quot; will not be imported.</p></div><ol><li>Login to your Trakt account and go to the settings page.</li><li>If your account is set to private, uncheck the box next to it. You can revert this change once the import is complete.</li><li>If you have any lists that are private, you need to change them to public. Otherwise they will not be imported.</li><li>Find your profile slug. This is usually your username. You can find it by going to your profile page, and checking the URL.</li><li>Enter this username in the input.</li></ol><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to “List”">​</a></h2><p>All items from a public Trakt list can be imported and added to the collection of your choice.</p><ol><li>Enter a URL for the list to import. For example:</li></ol><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://trakt.tv/users/felix66/lists/trakt-movie-the-new-york-times-guide-to-the-best-1-000-movies-ever-made?sort=rank,asc</span></span></code></pre></div><ol start="2"><li>Select the collection you want to import the items into.</li></ol><h2 id="export-zip" tabindex="-1">Export ZIP <a class="header-anchor" href="#export-zip" aria-label="Permalink to “Export ZIP”">​</a></h2><p>You can request a ZIP export of your Trakt data from the <a href="https://app.trakt.tv/settings/data" target="_blank" rel="noreferrer">Trakt data export settings</a>. This method imports your history, ratings, Owned, Watchlist, Favorites, custom lists, and comments.</p><ol><li>Request and download your export from the Trakt data export settings.</li><li>Leave the downloaded ZIP file intact. Do not extract or modify it.</li><li>In Ryot, select <strong>Trakt &gt; Export ZIP</strong> and upload the ZIP file.</li></ol><p>Ryot uses the watched-history files to import watched items and ignores aggregate watched files. Your Trakt profile and lists do not need to be public for this method, and a Trakt client ID is not required.</p>',16)])])}const m=e(r,[["render",s]]);export{u as __pageData,m as default};
